	'messages:apihelp-query-param-rawcontinue' => 'en:Return raw <samp>query-continue</samp> data for continuation.',
	'messages:apihelp-query-example-revisions' => 'en:Fetch [[Special:ApiHelp/query+siteinfo|site info]] and [[Special:ApiHelp/query+revisions|revisions]] of [[{{MediaWiki:Mainpage}}]].',
	'messages:apihelp-query-example-allpages' => 'en:Fetch revisions of pages beginning with <kbd>API/</kbd>.',
