	'messages:apihelp-query+alllinks-example-b' => 'en:List linked titles, including missing ones, with page IDs they are from, starting at <kbd>B</kbd>.',
	'messages:apihelp-query+alllinks-example-unique' => 'en:List unique linked titles.',
